{
  "facts": [
    {
      "topic": "contract",
      "statement": "For a tag with a quoted attribute containing byte 0xFF, the after scanner's quoted attribute loop accepts that byte. A closing quote, `>`, and newline can lead to its return value 7.",
      "evidence": [
        {
          "unit_id": "u-a1a08cffd1ca26310e68",
