          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-a1a08cffd1ca26310e68",
          "start_line": 7460,
          "end_line": 7483,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "counterevidence",
      "statement": "The before scanner's bitmap does not admit byte 0xFF in the quoted attribute loop, and its explicit high byte path rejects bytes above 0xF4.",
      "evidence": [
        {
          "unit_id": "u-b355481778f3add37dfc",
          "start_line": 8017,
          "end_line": 8026,
          "role": "primary",
          "dependency_reason": ""
        },
        {
          "unit_id": "u-b355481778f3add37dfc",
          "start_line": 8356,
          "end_line": 8388,
          "role": "primary",
          "dependency_reason": ""
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "trigger",
      "statement": "The harness can put arbitrary bytes after its packed options and width fields into `cmark_parse_document`; its option mask permits UTF-8 validation to be unset.",
      "evidence": [
        {
          "unit_id": "u-01d44c1169261cd79a4c",
          "start_line": 10,
          "end_line": 33,
          "role": "dependency",
          "dependency_reason": "Establishes the finite fuzzer input route and selectable validation option for the scanner condition."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "configuration",
      "statement": "When `CMARK_OPT_VALIDATE_UTF8` is unset, line processing copies input bytes into the parser's current line rather than running UTF-8 validation.",
      "evidence": [
        {
          "unit_id": "u-f20dc521c971d4f66630",
          "start_line": 1279,
          "end_line": 1282,
          "role": "dependency",
          "dependency_reason": "Shows how the selected option preserves the invalid high byte before block scanning."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "target_route",
      "statement": "`scan_html_block_start_7` delegates to `_scan_at` with `_scan_html_block_start_7`; the supplied macro does not establish what `_scan_at` returns to its caller.",
      "evidence": [
        {
          "unit_id": "u-8dcbdd6d5c63141b4b6b",
          "start_line": 42,
          "end_line": 42,
          "role": "dependency",
          "dependency_reason": "Identifies the intervening wrapper that mediates the scanner result."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "alternative",
      "statement": "The harness also offers file, chunked parser, and `cmark_markdown_to_html` parsing routes, all using the markdown remainder and selected options.",
      "evidence": [
        {
          "unit_id": "u-01d44c1169261cd79a4c",
          "start_line": 24,
          "end_line": 62,
          "role": "dependency",
          "dependency_reason": "Preserves alternate input routes when assessing whether the behavior is unreachable."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "consequence",
      "statement": "If parsing creates an HTML block, the HTML renderer omits its raw content unless `CMARK_OPT_UNSAFE` is set; with that option it emits the block content. The harness permits that option and calls the renderer for a non-null document.",
      "evidence": [
        {
          "unit_id": "u-996d9a66e32c87a8332b",
          "start_line": 175,
          "end_line": 183,
          "role": "dependency",
          "dependency_reason": "Shows the renderer's behavior conditional on an HTML block being created."
        },
        {
          "unit_id": "u-01d44c1169261cd79a4c",
          "start_line": 19,
          "end_line": 22,
          "role": "dependency",
          "dependency_reason": "Shows that the fuzzer can select CMARK_OPT_UNSAFE."
        },
        {
          "unit_id": "u-01d44c1169261cd79a4c",
          "start_line": 64,
          "end_line": 71,
          "role": "dependency",
          "dependency_reason": "Shows the render call and disposal of its result."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    },
    {
      "topic": "counterevidence",
      "statement": "The complete old harness contains no assertion or output comparison that requires a type 7 HTML block; it parses, renders, frees results and the document, then returns zero.",
      "evidence": [
        {
          "unit_id": "u-01d44c1169261cd79a4c",
          "start_line": 1,
          "end_line": 75,
          "role": "dependency",
          "dependency_reason": "The entire entry point is needed to establish the limited absence of existing checks."
        }
      ],
      "absence_claim": true,
      "audited_unit_ids": [
        "u-01d44c1169261cd79a4c"
      ]
    },
    {
      "topic": "configuration",
      "statement": "The supplied recipe configures with `cmake ../`, builds `cmark_static`, and links the fuzz entry with `build/src/libcmark.a`.",
      "evidence": [
        {
          "unit_id": "u-944c463f7c78bc0977c2",
          "start_line": 18,
          "end_line": 25,
          "role": "dependency",
          "dependency_reason": "Fixes the build route for this target."
        }
      ],
      "absence_claim": false,
      "audited_unit_ids": []
    }
  ],
  "missing_information": [
    "The complete before and after bodies of `src/scanners.c::_scan_at` are needed to establish whether the scanner's return value reaches block parsing through the wrapper."
  ],
  "requested_symbols": [
    "_scan_at"
  ],
